    private final Runnable tick=new Runnable(){public void run(){if(!active)return;updateClock();ensureTimes();long now=System.currentTimeMillis();
        if(now-lastScan>60000)scanPhotos();if(now-lastAgenda>60000){lastAgenda=now;loadAgenda();}if(now-lastWeather>1800000)loadWeather();
        if(showingPhotos && now-lastPhoto>prefs.getInt("slide",20)*1000L)nextPhoto();
        if(!showingPhotos && screen!=4 && !photos.isEmpty() && now-lastTouch>prefs.getInt("idle",120)*1000L)showSlideshow();
        if(showingPhotos)applyNightBrightness();ui.postDelayed(this,1000);}};

    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("hmhome",MODE_PRIVATE);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);lastTouch=System.currentTimeMillis();loadCached();build();}
    @Override protected void onResume(){super.onResume();active=true;lastTouch=System.currentTimeMillis();ui.removeCallbacks(tick);ui.post(tick);}
    @Override protected void onPause(){active=false;ui.removeCallbacks(tick);super.onPause();}
    @Override protected void onDestroy(){photoGeneration++;ui.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
    @Override public boolean dispatchTouchEvent(android.view.MotionEvent e){if(e.getAction()==android.view.MotionEvent.ACTION_DOWN){lastTouch=System.currentTimeMillis();if(showingPhotos){hideSlideshow();return true;}}return super.dispatchTouchEvent(e);}
    @Override public void onBackPressed(){if(showingPhotos)hideSlideshow();else{screen=0;build();}}
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private GradientDrawable bg(int c,int radius){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(radius));return d;}
    private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setFontFeatureSettings("tnum");return t;}
    private TextView title(String s,int size){TextView t=text(s,size,INK);t.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));return t;}
    private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private void space(LinearLayout l,int h){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
    private void line(LinearLayout l){View v=new View(this);v.setBackgroundColor(Color.rgb(232,222,211));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(1));p.topMargin=dp(12);p.bottomMargin=dp(12);l.addView(v,p);}
    private TextView action(String s,Runnable fn){TextView b=title(s,13);b.setGravity(Gravity.CENTER);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setBackground(bg(Color.rgb(231,222,209),12));b.setOnClickListener(v->fn.run());return b;}
    private LinearLayout card(String heading){LinearLayout c=col();c.setPadding(dp(22),dp(18),dp(22),dp(18));c.setBackground(bg(CARD,22));c.addView(text(heading.toUpperCase(Locale.UK),11,MUTED));space(c,12);return c;}
    private void weighted(LinearLayout parent,View child,float w,int right){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,w);p.rightMargin=dp(right);parent.addView(child,p);}

    private void build(){
        showingPhotos=false;photoGeneration++;photoView=null;prayerValues.clear();clock=date=nextName=nextCountdown=nextDetails=weather=prayerStatus=photoCount=null;agenda=null;
        shell=col();shell.setBackgroundColor(BG);shell.setPadding(dp(24),dp(18),dp(24),dp(18));
        LinearLayout head=row();ImageView logo=new ImageView(this);logo.setImageResource(getResources().getIdentifier("hm_logo","drawable",getPackageName()));logo.setScaleType(ImageView.ScaleType.CENTER_CROP);head.addView(logo,new LinearLayout.LayoutParams(dp(42),dp(42)));
        LinearLayout branding=col();branding.setPadding(dp(10),0,0,0);branding.addView(title("Hanna & Miqdad",17));branding.addView(text("HOME, TOGETHER",9,MUTED));head.addView(branding,new LinearLayout.LayoutParams(0,-2,1));
        String[] nav={"Home","Namaz","Agenda","Photos","Settings"};for(int i=0;i<nav.length;i++){final int n=i;TextView b=action(nav[i],()->{screen=n;build();});if(i==screen)b.setBackground(bg(Color.rgb(209,193,172),12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.leftMargin=dp(6);head.addView(b,p);}shell.addView(head);space(shell,18);
        body=col();shell.addView(body,new LinearLayout.LayoutParams(-1,0,1));setContentView(shell);
        if(screen==0)home();else if(screen==1)namaz();else if(screen==2)agendaScreen();else if(screen==3)photosScreen();else settings();
        updateClock();ensureTimes();loadAgenda();
    }
    private void home(){
        LinearLayout columns=row();columns.setGravity(Gravity.TOP);body.addView(columns,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout left=col();weighted(columns,left,1.0f,16);clock=title("",62);left.addView(clock);date=text("",14,MUTED);left.addView(date);space(left,12);weather=text(weatherText,14,INK);left.addView(weather);space(left,20);
        LinearLayout prayer=card("Next Namaz · London");nextName=title("Loading timetable",24);nextCountdown=title("—",34);nextDetails=text("Hujjat timetable",12,MUTED);prayer.addView(nextName);space(prayer,4);prayer.addView(nextCountdown);space(prayer,5);prayer.addView(nextDetails);space(prayer,12);prayer.addView(action("View timetable",()->{screen=1;build();}));left.addView(prayer,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout right=card("Your day");weighted(columns,right,1.3f,0);LinearLayout ar=row();ar.addView(title("Coming up",24),new LinearLayout.LayoutParams(0,-2,1));ar.addView(action("Calendars",this::calendarPicker));right.addView(ar);line(right);ScrollView sc=new ScrollView(this);agenda=col();sc.addView(agenda);right.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
        space(body,14);LinearLayout footer=row();footer.addView(action("Living room controls  ↗",this::openGoogleHome),new LinearLayout.LayoutParams(0,-2,1));TextView photo=action("Photo frame",this::showSlideshow);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.leftMargin=dp(12);footer.addView(photo,p);body.addView(footer);
    }
    private void namaz(){LinearLayout c=card("Hujjat · London");body.addView(c,new LinearLayout.LayoutParams(-1,-1));LinearLayout top=row();nextName=title("Loading",28);top.addView(nextName,new LinearLayout.LayoutParams(0,-2,1));nextCountdown=title("—",28);top.addView(nextCountdown);c.addView(top);nextDetails=text("",13,MUTED);c.addView(nextDetails);line(c);
        String[] keys={"imsaak","fajr","sunrise","zohr","sunset","maghrib"};String[] labels={"Imsaak","Fajr","Sunrise","Zohr","Sunset","Maghrib"};LinearLayout grid=row();for(int i=0;i<keys.length;i++){LinearLayout item=col();item.setPadding(dp(10),dp(14),dp(8),dp(14));item.addView(text(labels[i],13,MUTED));TextView v=title("—",24);item.addView(v);prayerValues.put(keys[i],v);grid.addView(item,new LinearLayout.LayoutParams(0,-2,1));}c.addView(grid);line(c);prayerStatus=text("",12,MUTED);c.addView(prayerStatus);space(c,14);c.addView(text("Nest reminders run independently through your Cloudflare service.\nMaghrib uses the Maghrib time, not sunset. No separate Asr or Isha times are supplied.",13,INK));space(c,16);c.addView(action("Refresh timetable",()->{times.clear();fetching.clear();ensureTimes();updateClock();}));}
    private void agendaScreen(){LinearLayout c=card("Combined agenda");body.addView(c,new LinearLayout.LayoutParams(-1,-1));LinearLayout top=row();top.addView(title("The next seven days",26),new LinearLayout.LayoutParams(0,-2,1));top.addView(action("Choose calendars",this::calendarPicker));c.addView(top);line(c);ScrollView sc=new ScrollView(this);agenda=col();sc.addView(agenda);c.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
    private void photosScreen(){LinearLayout c=card("Your photo frame");body.addView(c,new LinearLayout.LayoutParams(-1,-1));c.addView(title("A little more of you",30));space(c,12);photoCount=text("",15,MUTED);c.addView(photoCount);space(c,18);c.addView(action("Choose local folder",this::chooseFolder));space(c,12);c.addView(action("Start slideshow",this::showSlideshow));space(c,12);c.addView(action("Refresh folder",()->{lastScan=0;scanPhotos();}));space(c,18);c.addView(text("Photos stay on this tablet. Tap the slideshow to return home.\nAdd or remove images in your chosen folder; the app checks it every minute.\nJPEG, PNG and WebP · files directly inside the folder",13,MUTED));updatePhotoLabel();}
    private void settings(){ScrollView sc=new ScrollView(this);LinearLayout c=card("Make yourself at home");sc.addView(c);body.addView(sc);c.addView(title("Dashboard settings",26));line(c);
        setting(c,"Start photo frame after",new String[]{"30 seconds","1 minute","2 minutes","5 minutes","10 minutes"},new int[]{30,60,120,300,600},"idle",120);
        setting(c,"Change photograph every",new String[]{"10 seconds","20 seconds","30 seconds","1 minute","5 minutes"},new int[]{10,20,30,60,300},"slide",20);
        toggle(c,"Shuffle photographs","shuffle",true);toggle(c,"Fill screen (crop edges)","fill",false);toggle(c,"Clock and Namaz overlay","overlay",true);toggle(c,"Dim photo frame from 22:00 to 07:00","night",true);
        space(c,12);c.addView(action("Choose photo folder",this::chooseFolder));space(c,10);c.addView(action("Choose device calendars",this::calendarPicker));space(c,10);c.addView(action("Open Google Home",this::openGoogleHome));line(c);
        c.addView(text("HM Home 0.1 · Personal preview\nPrayer times: Hujjat London API\nWeather: Open-Meteo (open-meteo.com), London\nThis app does not change or replace your Cloudflare schedule.\nGoogle Home controls open the Google Home app in this version.\nCalendars must already be synced to Android; direct Google/iCloud sign-in is not included.",12,MUTED));}
    private void setting(LinearLayout c,String label,String[] labels,int[] values,String key,int def){LinearLayout r=row();r.addView(text(label,14,INK),new LinearLayout.LayoutParams(0,-2,1));Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));int n=0;for(int i=0;i<values.length;i++)if(values[i]==prefs.getInt(key,def))n=i;s.setSelection(n);s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){prefs.edit().putInt(key,values[pos]).apply();}});r.addView(s,new LinearLayout.LayoutParams(dp(190),dp(48)));c.addView(r);}
    private void toggle(LinearLayout c,String label,String key,boolean def){Switch s=new Switch(this);s.setText(label);s.setTextColor(INK);s.setTextSize(14);s.setChecked(prefs.getBoolean(key,def));s.setPadding(0,dp(12),0,dp(12));s.setOnCheckedChangeListener((b,v)->prefs.edit().putBoolean(key,v).apply());c.addView(s);}
    private void updateClock(){ZonedDateTime now=ZonedDateTime.now(PrayerClock.LONDON);if(clock!=null)clock.setText(now.format(DateTimeFormatter.ofPattern("HH:mm")));if(date!=null)date.setText(now.format(DateTimeFormatter.ofPattern("EEEE, d MMMM",Locale.UK)));Map<String,String> today=times.getOrDefault(now.toLocalDate().toString(),Collections.emptyMap()),tomorrow=times.getOrDefault(now.toLocalDate().plusDays(1).toString(),Collections.emptyMap());PrayerClock.Next n=PrayerClock.next(now,today,tomorrow);
        if(nextName!=null)nextName.setText(n==null?"Timetable unavailable":n.label);if(nextCountdown!=null)nextCountdown.setText(n==null?"—":"In "+n.countdown());if(nextDetails!=null)nextDetails.setText(n==null?(prayerError.isEmpty()?"Fetching London timetable…":prayerError):n.at.format(DateTimeFormatter.ofPattern("HH:mm"))+" · "+(n.at.toLocalDate().equals(now.toLocalDate())?"today":"tomorrow"));
        for(Map.Entry<String,TextView> e:prayerValues.entrySet())e.getValue().setText(today.getOrDefault(e.getKey(),"—"));if(prayerStatus!=null)prayerStatus.setText(prayerError.isEmpty()?"London · "+now.toLocalDate()+" · locally cached after download":prayerError);
        if(overlayClock!=null)overlayClock.setText(now.format(DateTimeFormatter.ofPattern("HH:mm")));if(overlayNext!=null)overlayNext.setText(n==null?"London timetable unavailable":n.label+" in "+n.countdown()+"  ·  "+n.at.format(DateTimeFormatter.ofPattern("HH:mm")));
    }
    private JSONObject getJson(String endpoint)throws Exception{HttpURLConnection con=(HttpURLConnection)new URL(endpoint).openConnection();con.setConnectTimeout(12000);con.setReadTimeout(12000);try{if(con.getResponseCode()!=200)throw new IOException("HTTP "+con.getResponseCode());try(InputStream in=con.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>1024*1024)throw new IOException("Response too large");}return new JSONObject(out.toString("UTF-8"));}}finally{con.disconnect();}}
    private void loadCached(){for(int i=0;i<2;i++){String day=LocalDate.now(PrayerClock.LONDON).plusDays(i).toString();try{String cached=prefs.getString("prayer:"+day,null);if(cached!=null)times.put(day,parseTimes(new JSONObject(cached)));}catch(Exception ignored){}}}
    private Map<String,String> parseTimes(JSONObject json)throws Exception{Map<String,String> map=new HashMap<>();for(String k:new String[]{"imsaak","fajr","sunrise","zohr","sunset","maghrib"}){String value=json.optString(k,"");if(!value.isEmpty()){PrayerClock.time(value);map.put(k,value);}}for(String k:PrayerClock.KEYS)if(!map.containsKey(k))throw new IOException("Missing prayer field");return map;}
    private final Map<String,Long> retryAfter=new ConcurrentHashMap<>();
    private void ensureTimes(){for(int i=0;i<2;i++){LocalDate d=LocalDate.now(PrayerClock.LONDON).plusDays(i);String day=d.toString();if(times.containsKey(day)||fetching.contains(day)||System.currentTimeMillis()<retryAfter.getOrDefault(day,0L))continue;fetching.add(day);io.execute(()->{try{JSONObject j=getJson(PrayerClock.endpoint(d));times.put(day,parseTimes(j));prefs.edit().putString("prayer:"+day,j.toString()).apply();prayerError="";}catch(Exception e){prayerError="Offline or timetable unavailable · retrying in one minute";retryAfter.put(day,System.currentTimeMillis()+60000);}finally{fetching.remove(day);ui.post(()->{if(active)updateClock();});}});}}
    private void loadWeather(){if(weatherLoading)return;weatherLoading=true;lastWeather=System.currentTimeMillis();io.execute(()->{try{JSONObject c=getJson("https://api.open-meteo.com/v1/forecast?latitude=51.5074&longitude=-0.1278&current=temperature_2m,weather_code&timezone=Europe%2FLondon").getJSONObject("current");int code=c.getInt("weather_code");String label=code==0?"Clear":code<=3?"Cloudy":code<=48?"Fog":code<=67?"Rain":code<=77?"Snow":code<=82?"Showers":"Changeable";weatherText=Math.round(c.getDouble("temperature_2m"))+"°  ·  "+label+"  ·  London";}catch(Exception e){weatherText="Weather unavailable · London";}finally{weatherLoading=false;ui.post(()->{if(weather!=null)weather.setText(weatherText);});}});}
    private void chooseFolder(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,100);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==100 && result==RESULT_OK && data!=null && data.getData()!=null){Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);String old=prefs.getString("folder",null);prefs.edit().putString("folder",uri.toString()).apply();if(old!=null&&!old.equals(uri.toString()))try{getContentResolver().releasePersistableUriPermission(Uri.parse(old),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}photos.clear();photoGeneration++;photoIndex=-1;lastScan=0;scanPhotos();}catch(Exception e){toast("The folder did not grant persistent access. Please choose another folder.");}}}
    private void scanPhotos(){if(scanning)return;lastScan=System.currentTimeMillis();String folder=prefs.getString("folder",null);if(folder==null){updatePhotoLabel();return;}scanning=true;io.execute(()->{List<Photo> found=new ArrayList<>();String error="";try{Uri tree=Uri.parse(folder);Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){if(c==null)throw new IOException("Folder unavailable");while(c.moveToNext()){String id=c.getString(0),name=c.getString(1),mime=c.getString(2);String lower=name==null?"":name.toLowerCase(Locale.ROOT);if((mime!=null&&(mime.equals("image/jpeg")||mime.equals("image/png")||mime.equals("image/webp")))||lower.endsWith(".jpg")||lower.endsWith(".jpeg")||lower.endsWith(".png")||lower.endsWith(".webp")){found.add(new Photo(DocumentsContract.buildDocumentUriUsingTree(tree,id),name==null?id:name));}}}found.sort((a,b)->a.name.compareToIgnoreCase(b.name));}catch(Exception e){error="Folder unavailable. Choose it again to restore access.";}String finalError=error;ui.post(()->{scanning=false;if(!folder.equals(prefs.getString("folder",null)))return;photos=found;photoError=finalError;updatePhotoLabel();if(showingPhotos && photos.isEmpty())hideSlideshow();});});}
    private void updatePhotoLabel(){if(photoCount!=null)photoCount.setText(!photoError.isEmpty()?photoError:prefs.getString("folder",null)==null?"Choose a folder to get started.":photos.size()+" photographs · refreshes every minute");}
    private void showSlideshow(){if(photos.isEmpty()){if(prefs.getString("folder",null)==null)chooseFolder();else{scanPhotos();toast("No supported photographs found yet. Check the Photos tab.");}return;}showingPhotos=true;photoGeneration++;photoRoot=new FrameLayout(this);photoRoot.setBackgroundColor(Color.BLACK);photoView=new ImageView(this);photoView.setScaleType(prefs.getBoolean("fill",false)?ImageView.ScaleType.CENTER_CROP:ImageView.ScaleType.FIT_CENTER);photoRoot.addView(photoView,new FrameLayout.LayoutParams(-1,-1));
        if(prefs.getBoolean("overlay",true)){LinearLayout overlay=col();overlay.setPadding(dp(26),dp(12),dp(26),dp(24));GradientDrawable shade=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x00000000,0xB0000000});overlay.setBackground(shade);overlayClock=text("",44,Color.WHITE);overlayNext=text("",15,Color.WHITE);overlay.addView(overlayClock);overlay.addView(overlayNext);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);photoRoot.addView(overlay,p);}else overlayClock=overlayNext=null;
        setContentView(photoRoot);applyNightBrightness();updateClock();nextPhoto();}
    private void applyNightBrightness(){int hour=ZonedDateTime.now(PrayerClock.LONDON).getHour();WindowManager.LayoutParams p=getWindow().getAttributes();p.screenBrightness=prefs.getBoolean("night",true)&&(hour>=22||hour<6)?0.08f:-1f;getWindow().setAttributes(p);}
    private void hideSlideshow(){showingPhotos=false;photoGeneration++;overlayClock=overlayNext=null;WindowManager.LayoutParams p=getWindow().getAttributes();p.screenBrightness=-1f;getWindow().setAttributes(p);screen=0;lastTouch=System.currentTimeMillis();build();}
    private void nextPhoto(){if(photos.isEmpty()||photoView==null)return;lastPhoto=System.currentTimeMillis();int next;if(prefs.getBoolean("shuffle",true)&&photos.size()>1){next=new Random().nextInt(photos.size()-1);if(next>=photoIndex)next++;}else next=(photoIndex+1)%photos.size();photoIndex=next;Photo photo=photos.get(next);int generation=photoGeneration;ImageView target=photoView;io.execute(()->{Bitmap bitmap=null;try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(photo.uri)){BitmapFactory.decodeStream(in,null,o);}o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1600||o.outHeight/o.inSampleSize>1200)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;try(InputStream in=getContentResolver().openInputStream(photo.uri)){bitmap=BitmapFactory.decodeStream(in,null,o);}if(bitmap==null)throw new IOException("Cannot decode photo");try(InputStream in=getContentResolver().openInputStream(photo.uri)){int orientation=new ExifInterface(in).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;}if(!matrix.isIdentity()){Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);if(rotated!=bitmap){bitmap.recycle();bitmap=rotated;}}}catch(IOException ignored){} }catch(Exception|OutOfMemoryError e){if(bitmap!=null)bitmap.recycle();bitmap=null;}
            Bitmap result=bitmap;ui.post(()->{if(generation!=photoGeneration||!showingPhotos||photoView!=target){if(result!=null)result.recycle();return;}if(result!=null)target.setImageBitmap(result);else toast("One photograph could not be opened; trying the next slide.");});});}
    private void calendarPicker(){if(checkSelfPermission(Manifest.permission.READ_CALENDAR)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.READ_CALENDAR},101);return;}io.execute(()->{List<String> names=new ArrayList<>(),ids=new ArrayList<>();try(Cursor c=getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{CalendarContract.Calendars._ID,CalendarContract.Calendars.CALENDAR_DISPLAY_NAME,CalendarContract.Calendars.ACCOUNT_NAME},null,null,CalendarContract.Calendars.CALENDAR_DISPLAY_NAME+" ASC")){if(c!=null)while(c.moveToNext()){ids.add(c.getString(0));names.add(c.getString(1)+" · "+c.getString(2));}}catch(Exception e){ui.post(()->toast("Unable to read the tablet's calendars."));return;}ui.post(()->{if(isFinishing())return;if(ids.isEmpty()){new AlertDialog.Builder(this).setTitle("No calendars synced yet").setMessage("Add MSPH and Horizon accounts to Android and enable calendar sync. For iCloud, use a trusted CalDAV sync app with an Apple app-specific password. HM Home reads calendars synced to this tablet; it does not connect to iCloud itself.").setPositiveButton("Open account settings",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_SYNC_SETTINGS))).setNegativeButton("Close",null).show();return;}Set<String> chosen=new HashSet<>(prefs.getStringSet("calendars",Collections.emptySet()));boolean[] checks=new boolean[ids.size()];for(int i=0;i<ids.size();i++)checks[i]=chosen.contains(ids.get(i));new AlertDialog.Builder(this).setTitle("Choose calendars to display").setMultiChoiceItems(names.toArray(new String[0]),checks,(d,n,v)->{if(v)chosen.add(ids.get(n));else chosen.remove(ids.get(n));}).setPositiveButton("Save",(d,w)->{prefs.edit().putStringSet("calendars",chosen).apply();loadAgenda();}).setNegativeButton("Cancel",null).show();});});}
